#!/usr/bin/env bash
# external-secrets/external-secrets 2.8.0 - base variant: no-crds
# Path: fetch this entry's retained objects, check their SHA-256, then apply
# them with kubectl. It uses curl, shasum, awk and kubectl. It needs no cub
# CLI and no ConfigHub account.
# Generated by scripts/generate-public-site.mjs from this entry's listing:
# https://confighub.github.io/helm-expt/site/listings/external-secrets-external-secrets-2-8-0-no-crds.json
# Entry page: https://confighub.github.io/helm-expt/site/charts/external-secrets-external-secrets-2-8-0.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

for tool in curl awk kubectl; do
  if ! command -v "$tool" >/dev/null 2>&1; then
    printf '%s is required and was not found.\n' "$tool" >&2
    exit 1
  fi
done
if command -v shasum >/dev/null 2>&1; then
  sha256_of() { shasum -a 256 "$1" | awk '{print $1}'; }
elif command -v sha256sum >/dev/null 2>&1; then
  sha256_of() { sha256sum "$1" | awk '{print $1}'; }
else
  printf 'shasum is required and was not found.\n' >&2
  exit 1
fi

work=./external-secrets-external-secrets-2-8-0-no-crds-objects
objects_url=https://raw.githubusercontent.com/confighub/helm-expt/main/recipes/external-secrets/external-secrets/2.8.0/revisions/no-crds/r001/rendered/release-objects.yaml
objects_sha256=75ce0bfaa1c4ed14044edbd406eaa256987967a395676e2902a280e9abfa3304

say "Fetch the retained objects into $work/objects.yaml"
mkdir -p "$work"
curl -fsSL -o "$work/objects.yaml" "$objects_url"

say "Check the file against the SHA-256 in the listing"
fetched_sha256="$(sha256_of "$work/objects.yaml")"
if [ "$fetched_sha256" != "$objects_sha256" ]; then
  printf 'The file differs from the listing, so the script stops. Nothing was applied.\n  listing: %s\n  fetched: %s\n' "$objects_sha256" "$fetched_sha256" >&2
  exit 1
fi
printf 'The file matches: sha256 %s\n' "$fetched_sha256"

say "Split the file into its 19 objects. The cluster is untouched so far"
rm -rf "$work/docs" "$work/rest"
mkdir -p "$work/docs" "$work/rest"
awk -v dir="$work/docs" 'BEGIN { n = 0; f = sprintf("%s/doc-%04d.yaml", dir, n) } /^---[ \t]*$/ { close(f); n++; f = sprintf("%s/doc-%04d.yaml", dir, n); next } { print > f }' "$work/objects.yaml"
for n in 0001 0002 0003 0004 0005 0006 0007 0008 0009 0010 0011 0012; do mv "$work/docs/doc-$n.yaml" "$work/rest/"; done
for n in 0013 0014 0015 0016 0017 0018 0019; do mv "$work/docs/doc-$n.yaml" "$work/rest/"; done
ls "$work/rest"

if [ "${REQUIREMENTS_READY:-0}" != "1" ]; then
  say "Stop before applying anything. This entry's plan has 2 steps that an install needs first"
  cat >&2 <<'EOF_REQUIREMENTS'
This script cannot carry out these steps of the plan. They are yours to do, with your own values:
  - 25 CRDs must exist before apply. External Secrets CRD managed outside this no-crds base.
  - Secret external-secrets/external-secrets-webhook must exist before apply. Rendered webhook Secret separated by installer and populated by the cert-controller after apply.
Nothing was applied. Complete them before you apply the objects.
When they are done, re-run with:
  REQUIREMENTS_READY=1 bash try-objects.sh
EOF_REQUIREMENTS
  exit 1
fi
say "REQUIREMENTS_READY=1 is set. The script takes your word for 2 steps and does not check them"

say "Check that kubectl reaches a cluster"
if ! kubectl get --raw /version >/dev/null 2>&1; then
  printf 'kubectl cannot reach a cluster. Point it at a throwaway cluster and re-run this script.\n' >&2
  exit 1
fi
kubectl config current-context 2>/dev/null || true

say "Create the external-secrets namespace if it does not exist"
if ! kubectl get namespace external-secrets >/dev/null 2>&1; then
  kubectl create namespace external-secrets
fi

say "Apply the 19 objects"
kubectl apply -f "$work/rest"

say "Done. kubectl applied the 19 objects of this entry's retained file."
say "The script stops here. It did not wait for any workload to start"
say "Not run by this script: 2 steps of this entry's plan. The entry page says who runs each one."
cat <<'EOF_NOT_RUN'
   - 25 CRDs must exist before apply. External Secrets CRD managed outside this no-crds base.
   - Secret external-secrets/external-secrets-webhook must exist before apply. Rendered webhook Secret separated by installer and populated by the cert-controller after apply.
EOF_NOT_RUN
